/* DO NOT EDIT THIS FILE */

#ifndef INCLUDE_PLATFORM_H_
#define INCLUDE_PLATFORM_H_

/*
 * Thin portability layer (POSIX / Windows) used by the code that is provided to the students.
 * Nothing in here is needed to complete the lab.
 */

#include <stdbool.h>
#include <stdint.h>

#ifndef _WIN32
#include <pthread.h>
#endif

typedef struct platform_thread {
#ifdef _WIN32
    void* handle;
    void* (*function)(void*);
    void* argument;
#else
    pthread_t handle;
#endif
} platform_thread_t;

/* Monotonic clock, in microseconds. */
uint64_t platform_now_us(void);

/* User and system CPU time consumed by the process so far, in microseconds. */
int platform_cpu_times_us(uint64_t* user_us, uint64_t* system_us);

void platform_sleep_ms(unsigned int milliseconds);

int platform_thread_start(platform_thread_t* thread, void* (*function)(void*), void* argument);
int platform_thread_join(platform_thread_t* thread);

/* Unbuffered, non-echoing keyboard input. begin/end must bracket the calls to getch (no-ops on Windows). */
void platform_input_begin(void);
void platform_input_end(void);
/* Blocks until a key is pressed. Returns -1 on end of input. */
int platform_getch(void);

/* Whether a graphical session seems to be available (always true outside of X11/Wayland systems). */
bool platform_has_display(void);

#endif /* INCLUDE_PLATFORM_H_ */
